import sys
import csv
import os
import random
from src.optimization import LayeredOptimizer
from src.heuristics import improved_sifting
import pandas as pd


def get_start_position(csv_filepath, header):
    if os.path.exists(csv_filepath):
        with open(csv_filepath, 'r') as fd:
            for line in fd:
                pass
            last_line = line
            if last_line.split(',')[0] != "Index":
                return int(last_line.split(',')[0]) + 1
            else:
                return 1
    else:
        insert_one(csv_filepath, header)
        return 1


def insert_one(filename, entry):
    with open(filename, 'a', newline='') as f:
        wrt = csv.writer(f)
        wrt.writerow(entry)


def calculate_cutoff(csv_file, num_nodes, files_per_bucket):
    with open(csv_file, 'r') as fd:
        rdr = csv.reader(fd)
        first_line = next(rdr)
        fl_idx, st_idx = 1, first_line.index("Status")
        nfls = 0
        n_cutoff = 0
        for ln in rdr:
            if int(ln[fl_idx].split('_')[1]) == num_nodes:
                nfls += 1
                if int(ln[st_idx]) != 2:
                    n_cutoff += 1
        if nfls != files_per_bucket:
            raise Exception(f"Wrong num files in bucket {num_nodes}, {files_per_bucket} != {nfls}")
    return n_cutoff / nfls


def calculate_cutoff_rome(csv_file, num_nodes_b, files_in_bucket):
    with open(csv_file, 'r') as fd:
        rdr = csv.reader(fd)
        first_line = next(rdr)
        tnodes_idx, st_idx = first_line.index("TotalNodes"), first_line.index("Status")
        nfls = 0
        n_cutoff = 0
        for ln in rdr:
            if int(ln[tnodes_idx]) // 5 * 5 == num_nodes_b:
                nfls += 1
                if int(ln[st_idx]) != 2:
                    n_cutoff += 1
        if nfls != files_in_bucket:
            raise Exception(f"Wrong num files in bucket {num_nodes_b}, {files_in_bucket} != {nfls}")
    return n_cutoff / nfls


def get_crossing_optvals(list_of_graphs):
    df = pd.read_csv("experiments/aesthetics/results/0_results.csv")
    df = df[df["Data"].isin(list_of_graphs)]
    grnames = df["Data"].to_list()
    objvals = df["ObjVal"].to_list()
    cr_map = {grnames[i_v]: objvals[i_v] for i_v in range(len(grnames))}
    return cr_map


def run_func(combo_idx, data_path, crossing_optval, time_limit=600):
    opt = LayeredOptimizer(data_path)
    tlimit = time_limit
    combo_map = ["Sym1", "Sym1.05", "Sym1.1", "Sym1.2", "Sym1.5", "Sym2", "Len1", "Len1.05", "Len1.1", "Len1.2", "Len1.5", "Len2", "Planar1", "Planar1.05", "Planar1.1", "Planar1.2", "Planar1.5", "Planar2", "Minmax1", "Minmax1.05", "Minmax1.1", "Minmax1.2", "Minmax1.5", "Minmax2"]
    combo_choice = combo_map[combo_idx]
    if combo_choice == "Sym1":  # ID=0
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval)])
    elif combo_choice == "Sym1.05":  # ID=1
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval * 1.05)])
    elif combo_choice == "Sym1.1":  # ID=2
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval * 1.1)])
    elif combo_choice == "Sym1.2":  # ID=3
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval * 1.2)])
    elif combo_choice == "Sym1.5":  # ID=4
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval * 1.5)])
    elif combo_choice == "Sym2":  # ID=5
        res = opt.optimize_layout(cutoff_time=tlimit, symmetry_maximization=True, hybrid_constraints=[("crossings", crossing_optval * 2)])
    elif combo_choice == "Len1":  # ID=6
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval)])
    elif combo_choice == "Len1.05":  # ID=7
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval * 1.05)])
    elif combo_choice == "Len1.1":  # ID=8
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval * 1.1)])
    elif combo_choice == "Len1.2":  # ID=9
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval * 1.2)])
    elif combo_choice == "Len1.5":  # ID=10
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval * 1.5)])
    elif combo_choice == "Len2":  # ID=11
        res = opt.optimize_layout(cutoff_time=tlimit, bendiness_reduction=True, hybrid_constraints=[("crossings", crossing_optval * 2)])
    elif combo_choice == "Planar1":  # ID=12
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval)])
    elif combo_choice == "Planar1.05":  # ID=13
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval * 1.05)])
    elif combo_choice == "Planar1.1":  # ID=14
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval * 1.1)])
    elif combo_choice == "Planar1.2":  # ID=15
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval * 1.2)])
    elif combo_choice == "Planar1.5":  # ID=16
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval * 1.5)])
    elif combo_choice == "Planar2":  # ID=17
        res = opt.optimize_layout(cutoff_time=tlimit, planarization=True, hybrid_constraints=[("crossings", crossing_optval * 2)])
    elif combo_choice == "Minmax1":  # ID=18
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval)])
    elif combo_choice == "Minmax1.05":  # ID=19
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval * 1.05)])
    elif combo_choice == "Minmax1.1":  # ID=20
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval * 1.1)])
    elif combo_choice == "Minmax1.2":  # ID=21
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval * 1.2)])
    elif combo_choice == "Minmax1.5":  # ID=22
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval * 1.5)])
    elif combo_choice == "Minmax2":  # ID=23
        res = opt.optimize_layout(cutoff_time=tlimit, min_max_crossings=True, hybrid_constraints=[("crossings", crossing_optval * 2)])

    gcr = opt.g.num_edge_crossings()
    bnds = sum(abs(e.n1.y - e.n2.y) for e in opt.g.edges)
    return sum(1 for nd in opt.g.nodes if not nd.is_anchor_node), sum(1 for ed in opt.g.edges if not ed.n1.is_anchor_node), opt.g.n_nodes, len(opt.g.edges), res.objval, gcr, bnds, res.runtime, res.status


